<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">BACK OFFICE</p><h1>Staff Management</h1><p class="page-subtitle">จัดการข้อมูล Staff ที่มี UserAccount อยู่แล้ว</p></div><button @click="reset">เพิ่ม Staff</button></header><form class="profile-card" @submit.prevent="save"><h2>{{ editing ? 'แก้ไข Staff' : 'สร้าง Staff' }}</h2><div class="profile-grid"><label>User ID<input v-model.number="form.userId" type="number" min="1" required :disabled="!!editing" /></label><label>Employee Code<input v-model="form.employeeCode" maxlength="40" required /></label><label>ชื่อ-นามสกุล<input v-model="form.fullName" maxlength="160" required /></label><label>เบอร์โทรศัพท์<input v-model="form.phone" /></label></div><p v-if="errorMessage" class="error">{{ errorMessage }}</p><button type="submit">บันทึก</button><button v-if="editing" type="button" class="secondary" @click="reset">ยกเลิก</button></form><div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!staff.length" class="state-card">ยังไม่มีข้อมูล Staff</div><div v-else class="patient-results"><article v-for="item in staff" :key="item.id" class="patient-result-card"><div><span class="patient-hn">{{ item.employeeCode }} · {{ item.role }}</span><h2>{{ item.fullName }}</h2><p>{{ item.username }} · {{ item.phone || '-' }}</p></div><div><span class="status-badge" :class="{ inactive: !item.active }">{{ item.active ? 'Active' : 'Inactive' }}</span><div class="actions"><button class="secondary" @click="edit(item)">แก้ไข</button><button v-if="item.active" class="secondary" @click="deactivate(item)">ปิดใช้งาน</button></div></div></article></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { createStaff, deactivateStaff, listStaff, updateStaff, type Staff, type StaffPayload } from '../api/staff'; const staff=ref<Staff[]>([]),loading=ref(true),editing=ref<number|null>(null),errorMessage=ref(''); const empty=():StaffPayload=>({userId:0,employeeCode:'',fullName:'',phone:''}); const form=ref(empty()); async function load(){loading.value=true;try{staff.value=await listStaff()}catch(e){errorMessage.value=e instanceof Error?e.message:'โหลดข้อมูลไม่สำเร็จ'}finally{loading.value=false}} function reset(){editing.value=null;form.value=empty();errorMessage.value=''} function edit(item:Staff){editing.value=item.id;form.value={userId:item.userId,employeeCode:item.employeeCode,fullName:item.fullName,phone:item.phone||''};errorMessage.value=''} async function save(){errorMessage.value='';try{if(editing.value)await updateStaff(editing.value,form.value);else await createStaff(form.value);reset();await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'บันทึกไม่สำเร็จ'}} async function deactivate(item:Staff){try{await deactivateStaff(item.id);await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'ปิดใช้งานไม่สำเร็จ'}} onMounted(load)</script>
